import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
  Easing,
} from '../remotionShim';
// --- Google Fonts Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// ---------------------------



export type CountdownTimerProps = Record<string, any>;

const CountdownTimer: React.FC<CountdownTimerProps> = ({
  backgroundColor = "#111111",
  timerColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  startMinutes = 5,
  fontSize = 250,
  shakeStrength = 15,
}) => {
  useFontLoader(["Roboto Mono"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Logic to prevent parser errors ---
  const validStartMinutes = Math.max(1, startMinutes);
  const totalSeconds = validStartMinutes * 60;
  
  // Define phases for the animation
  // Phase 1: Rapid countdown from Start -> 5 seconds remaining (85% of video)
  // Phase 2: Snap to clarity, 5 -> 0 seconds (15% of video)
  const videoTotalFrames = durationInSeconds * fps;
  const fastPhaseFrames = Math.floor(videoTotalFrames * 0.85);
  const slowPhaseFrames = videoTotalFrames - fastPhaseFrames;

  // Calculate current "virtual" time remaining
  let timeRemaining = 0;
  
  if (frame < fastPhaseFrames) {
    // Phase 1: Accelerating/Fast
    // Interpolate from TotalSeconds down to 5.5
    // Use an easing that accelerates (starts slower, gets faster)
    const t = interpolate(frame, [0, fastPhaseFrames], [0, 1], {
      extrapolateRight: "clamp",
    });
    // Custom easing to simulate "acceleration" -> slowly starting to drop then rushing
    const easedT = Easing.in(Easing.poly(3))(t); 
    
    timeRemaining = interpolate(
      easedT,
      [0, 1],
      [totalSeconds, 6] // Go down to 6 to leave room for the final 5 countdown
    );
  } else {
    // Phase 2: The final 5 seconds (5, 4, 3, 2, 1, 0)
    // Map the remaining frames strictly to 5 -> 0
    const progressInSlow = frame - fastPhaseFrames;
    timeRemaining = interpolate(
      progressInSlow,
      [0, slowPhaseFrames],
      [5.99, 0], // Start just under 6
      { extrapolateRight: "clamp" }
    );
  }

  // Ensure we don't go below 0
  timeRemaining = Math.max(0, timeRemaining);

  // Formatting MM:SS
  const mins = Math.floor(timeRemaining / 60);
  const secs = Math.floor(timeRemaining % 60);
  const formattedTime = `${mins}:${secs.toString().padStart(2, "0")}`;

  // --- Motion Accents ---

  // 1. Shake Effect:
  // Shake increases as we speed up, then stabilizes for the final numbers, then huge impact at 0
  let currentShake = 0;
  
  if (frame < fastPhaseFrames) {
    // Shake based on acceleration (closer to end of fast phase = more shake)
    const progress = frame / fastPhaseFrames;
    currentShake = interpolate(progress, [0, 1], [2, shakeStrength]);
  } else {
    // Final phase: minor subtle shake, until the very end
    currentShake = 2;
  }
  
  // Random noise for shake
  const shakeX = random(frame) * currentShake - (currentShake / 2);
  const shakeY = random(frame + 100) * currentShake - (currentShake / 2);

  // 2. Scale Pulse on Minutes & Final Seconds
  // We detect "beats" when the second integer changes
  // We need a stable value to drive the spring, so we use the integer part of timeRemaining
  const timeInt = Math.floor(timeRemaining);
  
  // Determine if we are at a "major" jump (minutes or final seconds)
  // For the fast part, we only pulse on minutes. For slow part, pulse on every second.
  const isFinalPhase = timeRemaining < 6;
  const pulseTrigger = isFinalPhase ? timeInt : Math.floor(timeRemaining / 60);

  const scaleSpring = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 200,
      mass: 0.5,
    },
    from: 0,
    to: pulseTrigger % 2 === 0 ? 1 : 1.05, // Toggle target to keep spring active/changing
  });

  // Since spring to a changing target is tricky, let's use a simpler "Kick" approach
  // We trigger a kick whenever the integer second changes in the final phase
  // Or every ~30 frames in the fast phase if we want rhythmic pulsing
  
  // Alternative Pulse Strategy:
  // Calculate a "beat" value. 
  // If we are in fast phase, beat is faster.
  const scalePulse = interpolate(
    Math.sin(frame * (isFinalPhase ? 0.8 : 0.2)),
    [-1, 1],
    [1, 1.02]
  );
  
  // Big Impact at 0:00
  const isFinished = timeRemaining <= 0.05;
  const finishScale = spring({
    frame: frame - (videoTotalFrames - 15), // Trigger slightly before end or exactly at end
    fps,
    config: { damping: 10, stiffness: 100 },
    from: 1,
    to: isFinished ? 1.5 : 1,
  });

  const finalScale = isFinished ? finishScale : scalePulse;

  // 3. Blur / Flicker Effect
  // Higher blur during fast movement
  const blurAmount = interpolate(
    frame,
    [0, fastPhaseFrames, videoTotalFrames],
    [0, 6, 0], // Peak blur at max speed point (transition between fast/slow)
    { extrapolateRight: "clamp" }
  );

  // Opacity Trails (Echo)
  const renderEcho = (offsetFrames: number, opacity: number) => {
     // This is a visual approximation, real echoes would require history of timeRemaining
     // Instead, we just offset position slightly based on shake
     return (
        <h1
            style={{
                fontFamily: "Roboto Mono",
                fontSize: fontSize,
                fontWeight: 700,
                color: timerColor,
                position: "absolute",
                left: "50%",
                top: "50%",
                transform: `translate(-50%, -50%) translate(${shakeX * offsetFrames}px, ${shakeY * offsetFrames}px) scale(${finalScale})`,
                opacity: opacity,
                filter: `blur(${blurAmount + 2}px)`,
                margin: 0,
                padding: 0,
                fontVariantNumeric: "tabular-nums",
                whiteSpace: "nowrap",
            }}
        >
            {formattedTime}
        </h1>
     )
  }

  const bg = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bg }}>
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* Echo Layers for Speed Trail */}
        {!isFinished && frame > 10 && renderEcho(2, 0.2)}
        {!isFinished && frame > 5 && renderEcho(1, 0.4)}

        {/* Main Timer */}
        <h1
          style={{
            fontFamily: "Roboto Mono",
            fontSize: fontSize,
            fontWeight: 700,
            color: timerColor,
            margin: 0,
            padding: 0,
            fontVariantNumeric: "tabular-nums",
            whiteSpace: "nowrap",
            // Composite Transform: Center + Shake + Scale
            transform: `translate(${shakeX}px, ${shakeY}px) scale(${finalScale})`,
            filter: `blur(${isFinished ? 0 : blurAmount}px)`,
            textShadow: isFinished ? `0 0 50px ${timerColor}` : "none",
          }}
        >
          {formattedTime}
        </h1>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CountdownTimer;